}

pub(super) fn forge(cwd: &Path, cid: &str, field: &str, replacement: Value) -> String {
    let store = ObjectStore::open(cwd);
    let Node::Value(Value::Map(mut entries)) =
        decode_node(&store.get_canonical(cid).unwrap()).unwrap()
    else {
        panic!("composition-call receipt must be a value map")
    };
    entries
